//! Raw FFI bindings to `libdeluge`, generated by `bindgen` from its headers at build time.
//!
//! The build needs `libdeluge.a` and its headers under `DELUGE_SDK_ROOT` (default
//! `/usr/local`). Use `deluge-hal-linux` for a safe interface.

#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
